    "content": "import \"github.com/afreidah/g3/internal/backend\" Index Variables type BucketInfo type GetObjectResult type GmailBackend func NewGmailBackend(ctx context.Context, cfg *config.GmailConfig) (*GmailBackend, error) func (g *GmailBackend) CreateBucket(ctx context.Context, bucket string) error func (g *GmailBackend) DeleteObject(ctx context.Context, bucket, key string) error func (g *GmailBackend) GetObject(ctx context.Context, bucket, key string) (*GetObjectResult, error) func (g *GmailBackend) HeadObject(ctx context.Context, bucket, key string) (*HeadObjectResult, error) func (g *GmailBackend) ListBuckets(ctx context.Context) ([]BucketInfo, error) func (g *GmailBackend) ListObjects(ctx context.Context, bucket, prefix, delimiter, startAfter string, maxKeys int) (*ListObjectsResult, error) func (g *GmailBackend) PutObject(ctx context.Context, bucket, key string, body io.Reader, size int64, contentType string, metadata map[string]string) (string, error) type HeadObjectResult type ListObjectsResult type ObjectBackend type ObjectInfo type S3Error func (e *S3Error) Error() string Variables Sentinel errors for common S3 error conditions.\nvar ( ErrObjectNotFound = \u0026S3Error{StatusCode: 404, Code: \"NoSuchKey\", Message: \"The specified key does not exist\"} ErrBucketNotFound = \u0026S3Error{StatusCode: 404, Code: \"NoSuchBucket\", Message: \"The specified bucket does not exist\"} ErrBucketExists = \u0026S3Error{StatusCode: 409, Code: \"BucketAlreadyOwnedByYou\", Message: \"Your previous request to create the named bucket succeeded\"} ) type BucketInfo BucketInfo describes a bucket in a ListBuckets response.\ntype BucketInfo struct { Name string CreationDate time.Time } type GetObjectResult GetObjectResult holds the response data from a GetObject operation.\ntype GetObjectResult struct { Body io.ReadCloser Size int64 ContentType string ETag string LastModified time.Time Metadata map[string]string } type GmailBackend GmailBackend implements ObjectBackend using the Gmail API.\ntype GmailBackend struct { // contains filtered or unexported fields } func NewGmailBackend func NewGmailBackend(ctx context.Context, cfg *config.GmailConfig) (*GmailBackend, error) NewGmailBackend creates a GmailBackend from the provided configuration. It builds an OAuth2 token source from the configured client credentials and refresh token, then initializes the Gmail API client.\nfunc (*GmailBackend) CreateBucket func (g *GmailBackend) CreateBucket(ctx context.Context, bucket string) error CreateBucket creates a new Gmail label for the given bucket name.\nfunc (*GmailBackend) DeleteObject func (g *GmailBackend) DeleteObject(ctx context.Context, bucket, key string) error DeleteObject removes an object by finding and trashing the corresponding Gmail message. Returns nil if the object does not exist (S3 idempotency).\nfunc (*GmailBackend) GetObject func (g *GmailBackend) GetObject(ctx context.Context, bucket, key string) (*GetObjectResult, error) GetObject retrieves an object from Gmail by searching for the email with the matching subject line, then parsing the MIME message to extract metadata and attachment data.\nfunc (*GmailBackend) HeadObject func (g *GmailBackend) HeadObject(ctx context.Context, bucket, key string) (*HeadObjectResult, error) HeadObject retrieves only the metadata for an object without downloading the attachment data. Uses Gmail’s format=full to fetch the body text (JSON metadata) without the attachment content.\nfunc (*GmailBackend) ListBuckets func (g *GmailBackend) ListBuckets(ctx context.Context) ([]BucketInfo, error) ListBuckets returns all Gmail labels that match the configured label prefix, interpreted as S3 buckets.\nfunc (*GmailBackend) ListObjects func (g *GmailBackend) ListObjects(ctx context.Context, bucket, prefix, delimiter, startAfter string, maxKeys int) (*ListObjectsResult, error) ListObjects searches Gmail for emails matching the given bucket and prefix, returning results in S3 ListObjectsV2 format with delimiter and pagination support.\nfunc (*GmailBackend) PutObject func (g *GmailBackend) PutObject(ctx context.Context, bucket, key string, body io.Reader, size int64, contentType string, metadata map[string]string) (string, error) PutObject stores an object as a Gmail email with metadata body and data attachment. If an object with the same key already exists, it is deleted first (last-write-wins semantics).\ntype HeadObjectResult HeadObjectResult holds metadata from a HeadObject operation.\ntype HeadObjectResult struct { Size int64 ContentType string ETag string LastModified time.Time Metadata map[string]string } type ListObjectsResult ListObjectsResult holds the response from a ListObjectsV2 operation.\ntype ListObjectsResult struct { Contents []ObjectInfo CommonPrefixes []string IsTruncated bool NextStartAfter string } type ObjectBackend ObjectBackend defines the storage operations for the S3 gateway.\ntype ObjectBackend interface { PutObject(ctx context.Context, bucket, key string, body io.Reader, size int64, contentType string, metadata map[string]string) (etag string, err error) GetObject(ctx context.Context, bucket, key string) (*GetObjectResult, error) HeadObject(ctx context.Context, bucket, key string) (*HeadObjectResult, error) DeleteObject(ctx context.Context, bucket, key string) error ListObjects(ctx context.Context, bucket, prefix, delimiter, startAfter string, maxKeys int) (*ListObjectsResult, error) ListBuckets(ctx context.Context) ([]BucketInfo, error) CreateBucket(ctx context.Context, bucket string) error } type ObjectInfo ObjectInfo describes a single object in a listing response.\ntype ObjectInfo struct { Key string Size int64 LastModified time.Time ETag string } type S3Error S3Error represents a typed error that maps to an S3 HTTP error response.\ntype S3Error struct { StatusCode int Code string Message string } func (*S3Error) Error func (e *S3Error) Error() string Error implements the error interface.\nGenerated by gomarkdoc",
