    "content": "import \"github.com/afreidah/g3/internal/config\" Index func ParseLogLevel(level string) slog.Level type BucketConfig type Config func LoadConfig(path string) (*Config, error) func (c *Config) SetDefaultsAndValidate() error type CredentialConfig type GmailConfig type MetricsConfig type ServerConfig type TelemetryConfig func ParseLogLevel func ParseLogLevel(level string) slog.Level ParseLogLevel converts a log level string to slog.Level.\ntype BucketConfig BucketConfig defines an S3 bucket and its access credentials.\ntype BucketConfig struct { Name string `yaml:\"name\"` Credentials []CredentialConfig `yaml:\"credentials\"` } type Config Config is the root configuration for g3.\ntype Config struct { Server ServerConfig `yaml:\"server\"` Gmail GmailConfig `yaml:\"gmail\"` Buckets []BucketConfig `yaml:\"buckets\"` Telemetry TelemetryConfig `yaml:\"telemetry\"` } func LoadConfig func LoadConfig(path string) (*Config, error) LoadConfig reads and parses a YAML config file with environment variable expansion. Variables are referenced as ${VAR_NAME} in the YAML file.\nfunc (*Config) SetDefaultsAndValidate func (c *Config) SetDefaultsAndValidate() error SetDefaultsAndValidate applies defaults and validates the entire config tree. Returns an error listing all validation failures.\ntype CredentialConfig CredentialConfig holds an S3-compatible access key pair.\ntype CredentialConfig struct { AccessKeyID string `yaml:\"access_key_id\"` SecretAccessKey string `yaml:\"secret_access_key\"` } type GmailConfig GmailConfig holds Gmail API connection and behavior settings.\ntype GmailConfig struct { ClientID string `yaml:\"client_id\"` ClientSecret string `yaml:\"client_secret\"` RefreshToken string `yaml:\"refresh_token\"` User string `yaml:\"user\"` MaxAttachmentBytes int64 `yaml:\"max_attachment_bytes\"` ChunkSizeBytes int64 `yaml:\"chunk_size_bytes\"` LabelPrefix string `yaml:\"label_prefix\"` } type MetricsConfig MetricsConfig controls the Prometheus metrics endpoint.\ntype MetricsConfig struct { Enabled bool `yaml:\"enabled\"` Path string `yaml:\"path\"` } type ServerConfig ServerConfig holds HTTP server settings.\ntype ServerConfig struct { ListenAddr string `yaml:\"listen_addr\"` LogLevel string `yaml:\"log_level\"` ReadTimeout time.Duration `yaml:\"read_timeout\"` WriteTimeout time.Duration `yaml:\"write_timeout\"` ShutdownTimeout time.Duration `yaml:\"shutdown_timeout\"` } type TelemetryConfig TelemetryConfig holds metrics and tracing configuration.\ntype TelemetryConfig struct { Metrics MetricsConfig `yaml:\"metrics\"` Tracing telemetry.TracingConfig `yaml:\"tracing\"` } Generated by gomarkdoc",
